-- Contract 2.0.0-p (migrations 2026_12_27_000001 saved views, 2026_12_28_000001 attempt times; production 2bc45fc3
-- -> v1.1 with NAV section 0): each line must answer 1 after migrate; "-- after-rollback:" lines must answer 1 after
-- the rollback. Used by deploy/rehearse-migrations.sh --checks (which also compares the row counts of users,
-- capture_sessions, transcripts, session_labels and clients before and after each step).
-- After migrate: saved_views with its keys (primary id; unique workspace, person and client_ref; workspace, person and
-- position) and its two foreign keys (cascade on delete), and empty; users.views_version not null, default 0, 0 for
-- everyone; transcripts.attempt_started_at and recordings.upload_started_at nullable and empty (null: counted from
-- the end, else the start, as before). Nothing else changed: users, transcripts and recordings have exactly their
-- columns and indexes from production's migrations (2bc45fc3) plus the new column (transcripts keeps both FULLTEXT
-- indexes through the rebuild), and no other table is new. After rollback: all of that is gone, the rest as before.
select count(*) = 1 from information_schema.tables where table_schema = database() and table_name = 'saved_views';
select count(*) = 0 from saved_views;
select group_concat(column_name order by cast(column_name as binary) separator ',') = 'client_ref,created_at,density,filters,group_by,id,name,position,search,sort,updated_at,user_id,workspace_id' from information_schema.columns where table_schema = database() and table_name = 'saved_views';
select count(*) = 1 from information_schema.statistics where table_schema = database() and table_name = 'saved_views' and index_name = 'PRIMARY' and column_name = 'id';
select group_concat(column_name order by seq_in_index separator ',') = 'workspace_id,user_id,client_ref' from information_schema.statistics where table_schema = database() and table_name = 'saved_views' and index_name = 'saved_views_workspace_id_user_id_client_ref_unique' and non_unique = 0;
select group_concat(column_name order by seq_in_index separator ',') = 'workspace_id,user_id,position' from information_schema.statistics where table_schema = database() and table_name = 'saved_views' and index_name = 'saved_views_workspace_id_user_id_position_index';
select count(*) = 1 from information_schema.referential_constraints where constraint_schema = database() and table_name = 'saved_views' and constraint_name = 'saved_views_workspace_id_foreign' and referenced_table_name = 'workspaces' and delete_rule = 'CASCADE';
select count(*) = 1 from information_schema.referential_constraints where constraint_schema = database() and table_name = 'saved_views' and constraint_name = 'saved_views_user_id_foreign' and referenced_table_name = 'users' and delete_rule = 'CASCADE';
select count(*) = 2 from information_schema.referential_constraints where constraint_schema = database() and table_name = 'saved_views';
select count(*) = 1 from information_schema.columns where table_schema = database() and table_name = 'users' and column_name = 'views_version' and is_nullable = 'NO' and column_default = '0' and column_type like 'bigint%unsigned';
select count(*) = 0 from users where views_version <> 0;
select count(*) = 1 from information_schema.columns where table_schema = database() and table_name = 'transcripts' and column_name = 'attempt_started_at' and is_nullable = 'YES' and data_type = 'timestamp';
select count(*) = 0 from transcripts where attempt_started_at is not null;
select count(*) = 1 from information_schema.columns where table_schema = database() and table_name = 'recordings' and column_name = 'upload_started_at' and is_nullable = 'YES' and data_type = 'timestamp';
select count(*) = 0 from recordings where upload_started_at is not null;
select group_concat(column_name order by cast(column_name as binary) separator ',') = 'app_authentication_recovery_codes,app_authentication_secret,assist_settings,avatar_version,consent_seen_at,console_preferences,created_at,current_workspace_id,deletes_at,deletion_requested_at,email,email_preferences,email_restore,email_restore_address,email_restore_until,email_verified_at,entitlement_overrides,google_id,has_password,id,is_super_admin,name,notify_transcript_ready,password,recovery_codes_generated_at,remember_token,staff_role_id,support_access_until,suspended_at,suspended_reason,terms_accepted_at,transcription_key,transcription_key_checked_at,transcription_key_last4,transcription_key_provider,ui_classic,ui_design,updated_at,views_version' from information_schema.columns where table_schema = database() and table_name = 'users';
select group_concat(column_name order by cast(column_name as binary) separator ',') = 'attempt_started_at,attempts,capture_session_id,completed_at,created_at,edited_at,error,error_code,id,kind,language,meta,provider,provider_deleted_at,provider_job_id,provider_transcript_id,search_text,segments,status,submitted_at,text,updated_at' from information_schema.columns where table_schema = database() and table_name = 'transcripts';
select group_concat(column_name order by cast(column_name as binary) separator ',') = 'assembled_at,capture_session_id,channels,chunk_size_bytes,codec,created_at,declared_size_bytes,duration_ms,error,id,key_id,mime,received_chunks,role,sample_rate,sha256,stored_path,stored_size_bytes,total_chunks,updated_at,upload_started_at,upload_status' from information_schema.columns where table_schema = database() and table_name = 'recordings';
select group_concat(distinct index_name order by cast(index_name as binary) separator ',') = 'PRIMARY,users_current_workspace_id_foreign,users_deletes_at_index,users_email_restore_address_index,users_email_unique,users_google_id_unique,users_staff_role_id_foreign' from information_schema.statistics where table_schema = database() and table_name = 'users';
select group_concat(distinct index_name order by cast(index_name as binary) separator ',') = 'PRIMARY,transcripts_provider_job_id_index,transcripts_search_text_fulltext,transcripts_session_kind_provider_unique,transcripts_status_index,transcripts_text_fulltext' from information_schema.statistics where table_schema = database() and table_name = 'transcripts';
select group_concat(distinct index_name order by cast(index_name as binary) separator ',') = 'PRIMARY,recordings_capture_session_id_role_unique,recordings_upload_status_index' from information_schema.statistics where table_schema = database() and table_name = 'recordings';
select count(*) = 0 from information_schema.tables where table_schema = database() and table_name not in ('account_exports', 'admin_notes', 'app_releases', 'assist_prep_documents', 'assist_preps', 'assist_relay_checks', 'assist_sessions', 'assist_suggestions', 'assist_turns', 'assist_usage', 'audit_events', 'cache', 'cache_locks', 'call_notes', 'capture_sessions', 'client_briefs', 'client_contacts', 'client_files', 'client_keyterms', 'client_memory_items', 'clients', 'connected_apps', 'credentials', 'device_merges', 'device_pairing_codes', 'device_reports', 'device_sign_in_codes', 'devices', 'email_codes', 'failed_jobs', 'filing_rules', 'interface_flags', 'job_batches', 'jobs', 'known_browsers', 'label_colors', 'label_lists', 'migrations', 'missed_recordings', 'notifications', 'oauth_access_tokens', 'oauth_auth_codes', 'oauth_clients', 'oauth_refresh_tokens', 'passkeys', 'password_reset_tokens', 'personal_access_tokens', 'plans', 'plans_before_v16', 'promo_code_uses', 'promo_codes', 'provider_deletions', 'provider_requests', 'recordings', 'request_links', 'request_uploads', 'screens', 'sent_items', 'session_labels', 'session_markers', 'session_opens', 'sessions', 'settings', 'share_check_results', 'share_link_views', 'share_links', 'staff_roles', 'storage_deletions', 'transcript_revisions', 'transcripts', 'upgrade_request_proofs', 'upgrade_requests', 'usage_ledger', 'users', 'webhook_events', 'workspace_invitations', 'workspace_invite_links', 'workspace_user', 'workspaces', 'saved_views');
